using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<Researcher>();

var app = builder.Build();

var researcher = app.Services.GetRequiredService<Researcher>();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

await researcher.RunAsync(topic);

// ── Agent orchestrator ──────────────────────────────────────────────────────

sealed class Researcher(IChatClient chatClient, ResearchTools tools)
{
    public async Task RunAsync(string topic)
    {
        var systemPrompt = $"""
            You are a research agent. Your goal is to thoroughly research the following topic
            and produce a concise summary of your findings.

            Topic: {topic}

            Instructions:
            1. Search the web for relevant information (perform 2-3 searches with varied queries).
            2. Take notes on the key findings from each search.
            3. After gathering enough information, produce a final summary.

            Always take notes before moving on to the next search.
            When you have enough information, write the final summary directly in your response.
            """;

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [
                AIFunctionFactory.Create(tools.SearchWebAsync),
                AIFunctionFactory.Create(tools.TakeNote),
                AIFunctionFactory.Create(tools.GetNotes),
            ],
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, $"Please research this topic: {topic}"),
        };

        // Agent loop with iteration limit (guardrail)
        const int maxIterations = 15;
        var iteration = 0;

        while (iteration++ < maxIterations)
        {
            var response = await chatClient.GetResponseAsync(messages, chatOptions);

            // Append all response messages to the conversation
            foreach (var msg in response.Messages)
            {
                messages.Add(msg);
            }

            // Check if the model made any tool calls this turn
            bool hasToolCalls = response.Messages
                .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

            if (!hasToolCalls)
            {
                // No tool calls means the agent has finished reasoning
                var finalText = response.Messages
                    .Where(m => m.Role == ChatRole.Assistant)
                    .SelectMany(m => m.Contents.OfType<TextContent>())
                    .LastOrDefault()?.Text;

                if (!string.IsNullOrWhiteSpace(finalText))
                {
                    Console.WriteLine("═══ Research Summary ═══\n");
                    Console.WriteLine(finalText);
                }

                break;
            }

            Console.WriteLine($"  [Agent iteration {iteration}: processing tool calls...]");
        }

        if (iteration > maxIterations)
        {
            Console.WriteLine("\n⚠ Agent reached maximum iteration limit.");
        }

        Console.WriteLine($"\n── Notes collected ({tools.NoteCount}) ──");
        foreach (var note in tools.AllNotes)
        {
            Console.WriteLine($"  • {note}");
        }
    }
}

// ── Tools ────────────────────────────────────────────────────────────────────

sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;
    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Searches the web for the given query and returns relevant result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Uses the DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _http.GetStringAsync(url);

            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main summary)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(text);
                    }
                }
            }

            // Answer
            var answer = root.GetProperty("Answer").GetString();
            if (!string.IsNullOrWhiteSpace(answer))
            {
                results.Add($"[Answer] {answer}");
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note for later reference. Use this to record key findings.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved.");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }
}

