 sealed class ResearchTools
 {
     private readonly List<string> _notes = [];
     private readonly HttpClient _http = new();

     public int NoteCount => _notes.Count;
     public IReadOnlyList<string> AllNotes => _notes;

     [Description("Searches the web for the given query and returns relevant result snippets.")]
     public async Task<string> SearchWebAsync(
         [Description("The search query string")] string query)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await _http.GetStringAsync(url);

             var doc = System.Text.Json.JsonDocument.Parse(json);
             var root = doc.RootElement;

             var results = new List<string>();

             var abstractText = root.GetProperty("Abstract").GetString();
             var abstractSource = root.GetProperty("AbstractSource").GetString();
             if (!string.IsNullOrWhiteSpace(abstractText))
                 results.Add($"[{abstractSource}] {abstractText}");

             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var t in topics.EnumerateArray().Take(5))
                 {
                     var text = t.TryGetProperty("Text", out var v) ? v.GetString() : null;
                     if (!string.IsNullOrWhiteSpace(text))
                         results.Add(text);
                 }
             }

             var answer = root.GetProperty("Answer").GetString();
             if (!string.IsNullOrWhiteSpace(answer))
                 results.Add($"[Answer] {answer}");

             return results.Count == 0
                 ? $"No detailed results found for '{query}'. Try rephrasing the query."
                 : string.Join("\n\n", results);
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Saves a research note for later reference. Use this to record key findings.")]
     public string TakeNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📝 Note #{_notes.Count} saved.");
         return $"Note #{_notes.Count} saved successfully.";
     }

     [Description("Retrieves all previously saved research notes.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes have been saved yet.";

         return string.Join("\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
     }
 }

